def is_2digit_good(a, b):
    """Checks if the number 10*a + b is good, where a and b are nonzero and distinct."""
    m = 10 * a + b

    # Check if removing 'a' (leaving b) results in a divisor of m that is good.
    # b is always good (1-digit). Check if b | m.
    is_b_divisor = (m % b == 0)

    # Check if removing 'b' (leaving a) results in a divisor of m that is good.
    # a is always good (1-digit). Check if a | m.
    is_a_divisor = (m % a == 0)

    return is_a_divisor or is_b_divisor

good_2digit_numbers = []
for a in range(1, 10):
    for b in range(1, 10):
        if a != b:
            if is_2digit_good(a, b):
                good_2digit_numbers.append((a, b))

print("Good 2-digit numbers (tuple (a, b)):")
for ab in good_2digit_numbers:
    print(100*ab[0] + ab[1])

def get_digits(n):
    return [int(d) for d in str(n)]

def is_distinct_nonzero(m):
    digits = get_digits(m)
    return len(set(digits)) == len(digits) and all(d != 0 for d in digits)

# Check 1-digit numbers (Base Case)
# Always good
def is_good_1_digit(m):
    return True

# Check 2-digit numbers
# m = 10d1 + d2. Good if d1|d2 or d2|10d1
def is_good_2_digits(m):
    if not is_distinct_nonzero(m) or len(str(m)) != 2:
        return False
    d1 = m // 10
    d2 = m % 10
    # We assume d1 and d2 are nonzero since we filter input.
    return (d1 % d2 == 0) or (10 * d1 % d2 == 0)

# Check 3-digit numbers
# m = d1d2d3. Good if m' (2-digit) is good AND m' | m.
def is_good_3_digits(m):
    if not is_distinct_nonzero(m) or len(str(m)) != 3:
        return False
    d = get_digits(m)
    d1, d2, d3 = d[0], d[1], d[2]

    # Case A: Remove d1. m' = 10d2 + d3.
    m_prime_A = 10 * d2 + d3
    if is_good_2_digits(m_prime_A) and (m % m_prime_A == 0):
        return True

    # Case B: Remove d2. m' = 10d1 + d3.
    m_prime_B = 10 * d1 + d3
    if is_good_2_digits(m_prime_B) and (m % m_prime_B == 0):
        return True

    # Case C: Remove d3. m' = 10d1 + d2.
    m_prime_C = 10 * d1 + d2
    if is_good_2_digits(m_prime_C) and (m % m_prime_C == 0):
        return True

    return False

# Check 4-digit numbers
# m = d1d2d3d4. Good if m' (3-digit) is good AND m' | m.
def is_good_4_digits(m):
    if not is_distinct_nonzero(m) or len(str(m)) != 4:
        return False
    d = get_digits(m)
    d1, d2, d3, d4 = d[0], d[1], d[2], d[3]

    # Case A: Remove d1. m' = 100d2 + 10d3 + d4.
    m_prime_A = 100 * d2 + 10 * d3 + d4
    if is_good_3_digits(m_prime_A) and (m % m_prime_A == 0):
        return True

    # Case B: Remove d2. m' = 100d1 + 10d3 + d4.
    m_prime_B = 100 * d1 + 10 * d3 + d4
    if is_good_3_digits(m_prime_B) and (m % m_prime_B == 0):
        return True

    # Case C: Remove d3. m' = 100d1 + 10d2 + d4.
    m_prime_C = 100 * d1 + 10 * d2 + d4
    if is_good_3_digits(m_prime_C) and (m % m_prime_C == 0):
        return True

    # Case D: Remove d4. m' = 100d1 + 10d2 + d3.
    m_prime_D = 100 * d1 + 10 * d2 + d3
    if is_good_3_digits(m_prime_D) and (m % m_prime_D == 0):
        return True

    return False

def is_good(m):
    if len(str(m)) == 1:
        return is_good_1_digit(m)
    elif len(str(m)) == 2:
        return is_good_2_digits(m)
    elif len(str(m)) == 3:
        return is_good_3_digits(m)
    elif len(str(m)) == 4:
        return is_good_4_digits(m)
    return False

# --- Execution for targeted verification ---
START = 9876
END = 9375 # Check down to 9376 inclusive

largest_good_found = None

# Iterate backwards from 9876
for m in range(START, END, -1):
    if is_distinct_nonzero(m):
        if is_good(m):
            largest_good_found = m
            break

print(f"Largest good number found in range [9376, 9876]: {largest_good_found}")
